<script setup lang="ts">
// Role / Permission Management (generated by engineering-platform frontend-enterprise-management asset)
// Role list -> Role workspace: Basic Info + Permission Matrix (grouped) + Data Scope.
import { computed, onMounted, reactive, ref } from 'vue';
import PageHeader from '../../components/PageHeader.vue';
import PageContainer from '../../components/PageContainer.vue';
import SearchForm from '../../components/SearchForm.vue';
import AppTable from '../../components/AppTable.vue';
import StatusTag from '../../components/StatusTag.vue';
import PermissionButton from '../../permission/PermissionButton.vue';
import { roleApi, permissionApi } from '../../api/enterprise';
import type { Role, Permission, DataScope, EntityId } from '../../types/enterprise';
import { groupPermissions, actionLabel, resourceLabel, domainLabel } from '../../utils/permissionMatrix';
import { errorMessage, notifySuccess, toastSuccess } from '../../utils/feedback';

const loading = ref(false);
const listError = ref<string | null>(null);
const roles = ref<Role[]>([]);
const total = ref(0);
const page = ref(1);
const size = ref(20);
const filters = reactive({ keyword: '', enabled: null as boolean | null });

// permissions registry
const allPermissions = ref<Permission[]>([]);
const permissionGroups = computed(() => groupPermissions(allPermissions.value));
const selectedPermissions = ref<Set<EntityId>>(new Set());

// workspace state
const selectedRole = ref<Role | null>(null);
const creating = ref(false);
const editing = ref(false);
const workspaceError = ref<string | null>(null);
const saving = ref(false);

const roleForm = reactive({
  code: '',
  name: '',
  dataScope: 'SELF' as DataScope,
});

const DATA_SCOPES: { value: DataScope; label: string; description: string }[] = [
  { value: 'ALL', label: 'All data', description: 'Can see and manage all data in the system.' },
  { value: 'DEPARTMENT_AND_CHILDREN', label: 'Department & children', description: 'Data of own department and all sub-departments.' },
  { value: 'DEPARTMENT', label: 'Own department', description: 'Data of the own department only.' },
  { value: 'SELF', label: 'Own records', description: 'Only data created by the user themselves.' },
];

function dataScopeLabel(scope: string): string {
  return DATA_SCOPES.find((d) => d.value === scope)?.label ?? scope;
}

function dataScopeDescription(scope: string): string {
  return DATA_SCOPES.find((d) => d.value === scope)?.description ?? '';
}

async function loadRoles(): Promise<void> {
  loading.value = true;
  listError.value = null;
  try {
    const result = await roleApi.page({
      page: page.value,
      size: size.value,
      keyword: filters.keyword || undefined,
      enabled: filters.enabled ?? undefined,
    });
    roles.value = result.items;
    total.value = result.total;
  } catch (e) {
    listError.value = errorMessage(e);
  } finally {
    loading.value = false;
  }
}

async function loadPermissions(): Promise<void> {
  try {
    allPermissions.value = await permissionApi.list();
  } catch {
    allPermissions.value = [];
  }
}

function resetFilters(): void {
  filters.keyword = '';
  filters.enabled = null;
  page.value = 1;
  loadRoles();
}

function openWorkspace(role: Role): void {
  selectedRole.value = role;
  creating.value = false;
  editing.value = false;
  workspaceError.value = null;
  Object.assign(roleForm, { code: role.code, name: role.name, dataScope: role.dataScope });
  selectedPermissions.value = new Set(role.permissionIds);
}

function startCreate(): void {
  selectedRole.value = null;
  creating.value = true;
  editing.value = false;
  workspaceError.value = null;
  Object.assign(roleForm, { code: '', name: '', dataScope: 'SELF' });
  selectedPermissions.value = new Set();
}

function togglePermission(id: EntityId, checked: boolean): void {
  if (checked) {
    selectedPermissions.value.add(id);
  } else {
    selectedPermissions.value.delete(id);
  }
}

async function saveRole(): Promise<void> {
  saving.value = true;
  workspaceError.value = null;
  const permissionIds = [...selectedPermissions.value];
  try {
    if (creating.value) {
      await roleApi.create({ code: roleForm.code, name: roleForm.name, dataScope: roleForm.dataScope, permissionIds });
      notifySuccess('Role created');
    } else if (selectedRole.value) {
      await roleApi.update(selectedRole.value.id, { name: roleForm.name, dataScope: roleForm.dataScope });
      await roleApi.assignPermissions(selectedRole.value.id, permissionIds);
      notifySuccess('Role updated');
    }
    creating.value = false;
    editing.value = false;
    await loadRoles();
  } catch (e) {
    workspaceError.value = errorMessage(e);
  } finally {
    saving.value = false;
  }
}

async function setEnabled(role: Role, enabled: boolean): Promise<void> {
  try {
    if (enabled) {
      await roleApi.enable(role.id);
      toastSuccess('Role enabled');
    } else {
      await roleApi.disable(role.id);
      toastSuccess('Role disabled');
    }
    await loadRoles();
    if (selectedRole.value?.id === role.id) {
      selectedRole.value = { ...role, enabled };
    }
  } catch (e) {
    toastSuccess(errorMessage(e));
  }
}

onMounted(async () => {
  await Promise.all([loadRoles(), loadPermissions()]);
});
</script>

<template>
  <PageContainer full-width>
    <PageHeader title="Role & Permission Management" description="Roles define permission sets and data scope for the platform.">
      <template #actions>
        <PermissionButton permission="system:role:create" type="primary" data-testid="create-role" @click="startCreate">
          Create Role
        </PermissionButton>
      </template>
    </PageHeader>

    <SearchForm @search="loadRoles" @reset="resetFilters">
      <el-input v-model="filters.keyword" placeholder="Search code or name" clearable style="width: 240px" data-testid="role-search" />
      <el-select v-model="filters.enabled" placeholder="Status" clearable style="width: 140px" data-testid="role-filter-enabled">
        <el-option label="Enabled" :value="true" />
        <el-option label="Disabled" :value="false" />
      </el-select>
    </SearchForm>

    <AppTable
      :loading="loading"
      :error="listError"
      :data="roles"
      :total="total"
      :page="page"
      :size="size"
      @refresh="loadRoles"
      @update:page="(p: number) => { page = p; loadRoles(); }"
      @update:size="(s: number) => { size = s; page = 1; loadRoles(); }"
    >
      <el-table-column prop="code" label="Code" min-width="140" />
      <el-table-column prop="name" label="Name" min-width="160" />
      <el-table-column label="Status" width="110">
        <template #default="{ row }">
          <StatusTag :enabled="row.enabled" />
        </template>
      </el-table-column>
      <el-table-column label="Data scope" min-width="180">
        <template #default="{ row }">
          {{ dataScopeLabel(row.dataScope) }}
        </template>
      </el-table-column>
      <el-table-column label="Permissions" width="120">
        <template #default="{ row }">{{ row.permissionIds.length }}</template>
      </el-table-column>
      <el-table-column label="Actions" width="150" fixed="right">
        <template #default="{ row }">
          <el-button size="small" type="primary" link data-testid="role-open" @click="openWorkspace(row)">Open</el-button>
          <el-dropdown trigger="click">
            <el-button size="small" link>More</el-button>
            <template #dropdown>
              <el-dropdown-menu>
                <el-dropdown-item :disabled="row.enabled" @click="setEnabled(row, true)">Enable</el-dropdown-item>
                <el-dropdown-item :disabled="!row.enabled" @click="setEnabled(row, false)">Disable</el-dropdown-item>
              </el-dropdown-menu>
            </template>
          </el-dropdown>
        </template>
      </el-table-column>
    </AppTable>

    <el-alert
      v-if="creating || selectedRole"
      :title="creating ? 'New role' : 'Role workspace — ' + (selectedRole?.code ?? '')"
      :closable="false"
      type="info"
      class="workspace-banner"
      data-testid="role-workspace"
    >
      <template #default>
        <div class="role-workspace">
          <el-alert v-if="workspaceError" type="error" :title="workspaceError" :closable="false" class="form-alert" />
          <section class="workspace-section">
            <h3>Basic info</h3>
            <el-form :model="roleForm" label-width="120px" class="role-form">
              <el-form-item label="Code" :rules="[{ required: true, message: 'Code is required' }]">
                <el-input v-model="roleForm.code" :disabled="!creating" placeholder="e.g. ops-manager" data-testid="role-form-code" />
                <div v-if="!creating" class="form-hint">Code is immutable once created.</div>
              </el-form-item>
              <el-form-item label="Name">
                <el-input v-model="roleForm.name" data-testid="role-form-name" />
              </el-form-item>
              <el-form-item label="Data scope">
                <el-select v-model="roleForm.dataScope" style="width: 100%" data-testid="role-form-datascope">
                  <el-option v-for="d in DATA_SCOPES" :key="d.value" :label="d.label" :value="d.value" />
                </el-select>
                <div class="form-hint">{{ dataScopeDescription(roleForm.dataScope)?.description }}</div>
              </el-form-item>
            </el-form>
          </section>

          <section class="workspace-section">
            <h3>Permission matrix</h3>
            <div v-if="permissionGroups.length === 0" class="form-hint">No permissions registered.</div>
            <div v-for="group in permissionGroups" :key="group.domain" class="perm-domain" data-testid="perm-domain">
              <h4>{{ domainLabel(group.domain) }}</h4>
              <div v-for="res in group.resources" :key="res.resource" class="perm-resource">
                <span class="perm-resource-label">{{ resourceLabel(res.resource) }}</span>
                <el-checkbox
                  v-for="a in res.actions"
                  :key="a.permission.id"
                  :model-value="selectedPermissions.has(a.permission.id)"
                  :data-testid="'perm-' + (a.permission.code)"
                  @change="(v: string | number | boolean) => togglePermission(a.permission.id, Boolean(v))"
                >
                  {{ actionLabel(a.action) }}
                </el-checkbox>
              </div>
            </div>
          </section>

          <div class="workspace-actions">
            <el-button @click="creating = false; selectedRole = null">Close</el-button>
            <el-button type="primary" :loading="saving" data-testid="role-save" @click="saveRole">
              {{ creating ? 'Create' : 'Save changes' }}
            </el-button>
          </div>
        </div>
      </template>
    </el-alert>
  </PageContainer>
</template>

